1412	// write 是所有写入操作的统一入口：
1413	//   - reqNo 为空直接报错；
1414	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
1415	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
1416	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
1417	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
1418	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
1419		if reqNo == "" {
1420			return errors.New("请求编号不能为空")
1421		}
1422		s.mu.Lock()
1423		defer s.mu.Unlock()
1424		if err := s.lockExclusive(); err != nil {
1425			return err
1426		}
1427		defer s.unlock()
1428	
1429		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
1430		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
1431		if err := s.load(); err != nil {
1432			return err
1433		}
1434	
1435		payloadRaw, err := json.Marshal(payload)
1436		if err != nil {
1437			return err
1438		}
1439		payloadStr := string(payloadRaw)
1440	
1441		if req, ok := s.state.Requests[reqNo]; ok {
1442			if req.Op != op || req.Payload != payloadStr {
1443				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
1444					ErrRequestConflict, reqNo, req.Op, op)
1445			}
1446			// 保存的配方登记结果、创建批次结果、草稿调整结果、投料结果、开始执行
1447			// 结果与关闭结果都已在本次 load 的 validateState 中与实际登记内容核对
1448			// 一致（缺失、为 null、为空对象或内容不符都已在上面拒绝），这里取回的
1449			// 就是第一次成功的结果。
1450			if err := json.Unmarshal(req.Result, out); err != nil {
1451				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
1452			}
1453			return nil
1454		}
1455	
1456		clone, err := cloneState(s.state)
1457		if err != nil {
1458			return err
1459		}
1460		result, err := apply(clone)
1461		if err != nil {
1462			return err
1463		}
1464		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
1465		if err := s.persist(clone); err != nil {
1466			return fmt.Errorf("保存台账失败: %w", err)
1467		}
1468		s.state = clone
1469		if err := json.Unmarshal(result, out); err != nil {
1470			return fmt.Errorf("解析请求结果失败: %w", err)
1471		}
1472		return nil
1473	}
