1476	func (s *Store) read(fn func(*persistedState) error) error {
1477		s.mu.Lock()
1478		defer s.mu.Unlock()
1479		if err := s.lockShared(); err != nil {
1480			return err
1481		}
1482		defer s.unlock()
1483		if err := s.load(); err != nil {
1484			return err
1485		}
1486		return fn(s.state)
1487	}
