256		// 重放取回第一次成功登记的那条投料：序号 1、M1、显示 1 克、
257		// 时间与原投料为同一时刻、登记人张三。
258		replay, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
259		if err != nil {
