// （从 1 起；投料请求这类不按位置核对的场景传 0），text 是读到的克数原文。
//
// 它与 feedingContentMismatch 是两类必须可区分的损坏原因：克数写法本身无法
// 解析是克数非法；克数能解析、但取值或物料、时间、登记人与依据不一致是
// 内容不符。调用方不能把两者合并成一个泛化的比较失败。
type feedingGramError struct {
	where string
	pos   int
	text  string
}

func (e *feedingGramError) Error() string {
	return fmt.Sprintf("克数 %q 不合法", e.text)
}

// feedingContentMismatch 标记一处投料内容不符：where 说明拿保存结果与哪种
// 核对依据比较，pos 是该投料在按登记顺序逐条核对中的位置（从 1 起；投料
// 请求这类不按位置核对的场景传 0），m 列出具体不一致的维度。
type feedingContentMismatch struct {
	where string
	pos   int
	m     feedingMismatch
}

func (e *feedingContentMismatch) Error() string {
	return fmt.Sprintf("投料内容不一致（%s）", e.m.describe())
}

// describe 用中文列出不一致的维度，保持与原有“物料、克数、投料时间或登记人
// 不符”一致的可读说明，避免只报一个泛化的比较失败。
func (m feedingMismatch) describe() string {
	parts := make([]string, 0, 4)
	if m.material {
		parts = append(parts, "物料")
	}
	if m.grams {
		parts = append(parts, "克数")
	}
	if m.time {
		parts = append(parts, "投料时间")
	}
	if m.registrar {
		parts = append(parts, "登记人")
	}
	out := ""
	for i, p := range parts {
		if i > 0 {
			if i == len(parts)-1 {
				out += "或"
			} else {
				out += "、"
			}
		}
		out += p
	}
	return out + "不符"
}

// compareCloseFeedings 按关闭结果场景的业务依据，把保存结果中确认的投料
// 逐条与批次实际登记的投料对应：
//   - 条数必须相符：少一条、多一条都不接受，同物料的多次投料不能合并成
//     一条（即使合并后数量合计与分次合计相同）；
//   - 必须按登记顺序逐条对应：以投料在批次列表中的保存位置（第 1 条、第 2
//     条……）一一比较，不能按投料时间重新排序，也不能跳过或调换位置；
//   - 每个位置上序号必须与实际登记序号一致，内容（物料、克数、投料时间、
//     登记人）按 compareFeedingContent 的统一规则核对。
//
// 条数与顺序、序号是关闭结果特有的业务依据，在本函数内核对；“两条投料内容
// 是否相同”的判断与成功投料请求的核对共用 compareFeedingContent，两处不再
// 各自维护。克数非法与内容不符通过返回错误的具体类型区分，调用方据此包装
// 出带操作、请求编号、批次编号与出错投料位置的 ErrCorruptData 说明。
//
// got 是保存的关闭结果里的投料视图（按其保存顺序），want 是批次实际登记的
// 投料（按登记顺序）。
func compareCloseFeedings(got []FeedingView, want []feedingRecord) error {
	if len(got) != len(want) {
		return fmt.Errorf("投料条数 %d 与批次实际投料条数 %d 不一致，不能少一条、多一条或合并同物料的记录",
			len(got), len(want))
	}
	for i := range want {
		pos := i + 1
		rec := want[i]
		fv := got[i]
		// 序号是关闭结果特有的核对维度：按登记位置逐条对应时，该位置的序号
		// 必须就是实际登记序号，不能重排、改号。
		if fv.Seq != rec.Seq {
			return &feedingContentMismatch{where: "序号", pos: pos, m: feedingMismatch{}}
		}
		viewContent, ok := feedingContentFromView(fv)
		if !ok {
			return &feedingGramError{where: "保存结果", pos: pos, text: fv.Grams}
		}
		m := compareFeedingContent(viewContent, feedingContentFromRecord(rec))
		if m.anyMismatch() {
			return &feedingContentMismatch{where: "批次实际投料", pos: pos, m: m}
		}
	}
	return nil
}

